import { get_all_users } from "@/mixins/GetAllUsers.js";
import { update_department, change_location_head } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
export default {
  props: {
    editMasterDailog: Boolean,
    rowInfo: Object,
    tabName: String
  },
  mixins: [get_all_users],
  data() {
    return {
      departmentHead: "",
      masterUsers: [],
      searchF: null,
      loading: false
    };
  },
  watch: {
    editMasterDailog: {
      async handler() {
        if (this.editMasterDailog == true) {
          this.departmentHead = "";
          await this.get_all_users();
          this.fetch_users();
        }
      },
      immediate: true
    }
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
    },
    fetch_users() {
      this.masterUsers = [];
      this.departmentHead = "";
      this.listUsers.forEach(element => {
        this.masterUsers.push({
          label: element.full_user_name,
          value: element.user_id
        });
        this.masterUsers.sort((a, b) => a.label.localeCompare(b.label));
        if (element.full_user_name == (this.tabName == "Group" ? this.rowInfo.department_head : this.rowInfo.location_head)) {
          this.departmentHead = element.user_id;
        }
      });
    },
    async validate_data() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        if (this.tabName == "Group") {
          await this.edit_department_head();
        } else {
          await this.edit_location_head();
        }
      }
    },
    async edit_department_head() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(update_department, {
          input: {
            department_id: this.rowInfo.department_id,
            department_head: this.departmentHead
          }
        }));
        this.loading = false;
        this.$emit("successMsg", "Department Head Updated Successfully");
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    },
    async edit_location_head() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(change_location_head, {
          location_id: this.rowInfo.location_id,
          location_head: this.departmentHead
        }));
        this.loading = false;
        this.$emit("successMsg", "Group Head Updated Successfully");
      } catch (error) {
        this.$emit("errorMsg", error.errors[0].message);
        this.loading = false;
      }
    }
  }
};
